queries.core_box:
SELECT ?item ?coord ?sl WHERE { SERVICE wikibase:box { ?item wdt:P625 ?coord .
          bd:serviceParam wikibase:cornerSouthWest "Point(8.44 47.3)"^^geo:wktLiteral .
          bd:serviceParam wikibase:cornerNorthEast "Point(8.63 47.465)"^^geo:wktLiteral . }
          ?item wikibase:sitelinks ?sl }

queries.sitelinks:
SELECT ?item ?site ?title WHERE { VALUES ?item { %VALS% }
      VALUES ?site { <https://en.wikipedia.org/> <https://de.wikipedia.org/> <https://ru.wikipedia.org/> <https://fr.wikipedia.org/> <https://it.wikipedia.org/> <https://als.wikipedia.org/> <https://en.wikivoyage.org/> <https://de.wikivoyage.org/> <https://commons.wikimedia.org/> }
      ?article schema:about ?item ; schema:isPartOf ?site ; schema:name ?title . }
